  demo: false,
  canGet: false,
  canSet: false,
  mayWrite: false,
  draft: null,
  saved: null,
  recordId: null,
  running: null,
  runningError: null,
  err: null,
  aiSources: null,
  catalog: null,
  engine: { loaded: false, engine: '', modelDir: '', customDir: false },
  audio: { loaded: false, sendAudio: false, audioTranscript: false },
  waiting: { loaded: false, holdAndCallWaiting: false, autoHoldQueue: false, autoConnectPhone: true },
