#rs .chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
#rs .chip { display: inline-flex; align-items: center; gap: 5px; border-radius: 999px; background: var(--fl-surface-2); padding: 3px 5px 3px 10px; font-size: 11px; }
#rs .chip button { cursor: pointer; border: 0; background: transparent; color: var(--fl-faint); font-size: 14px; line-height: 1; padding: 0 2px; transition: color 0.15s ease; }
#rs .chip button:hover { color: var(--fl-bad); }
#rs .chip button:focus-visible { outline: 2px solid var(--fl-accent); outline-offset: 1px; border-radius: 6px; }

#rs #banner:empty { display: none; }
#rs #err { border: 1px solid var(--fl-bad); border-radius: 12px; padding: 10px 14px; font-size: 13px; color: var(--fl-bad);
  background: color-mix(in srgb, var(--fl-bad) 6%, transparent); overflow-wrap: break-word; }

#rs .running .greet { font-size: 13.5px; }
#rs .running .meta { margin-top: 3px; font-size: 11.5px; color: var(--fl-muted); }
#rs .running .persona { margin-top: 3px; font-size: 11px; color: var(--fl-faint); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }

/* Sticky save bar. #rs reserves 88px of bottom padding (more than the bar's
   height) so the last card's footnote always clears it at full scroll, and the
   bar's background is layered over var(--fl-bg) so it stays fully OPAQUE in
   both themes (the dark surface token is translucent on its own) - scrolling
