#rs .savebar { position: sticky; bottom: 8px; margin-top: 14px; z-index: 5; }
#rs .savebar .inner { border: 1px solid var(--fl-border); border-radius: 14px; padding: 10px 12px;
  background: linear-gradient(var(--fl-surface), var(--fl-surface)), var(--fl-bg);
