@supports ((backdrop-filter: blur(10px)) or (-webkit-backdrop-filter: blur(10px))) {
  #rs .savebar .inner {
    background: linear-gradient(var(--fl-surface), var(--fl-surface)), color-mix(in srgb, var(--fl-bg) 72%, transparent);
    -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px);
  }
}
#rs .savebar .right { margin-left: auto; display: flex; gap: 8px; flex-wrap: wrap; }
#rs .dirty { font-size: 11.5px; font-weight: 600; color: var(--fl-warn); }
#rs .clean { font-size: 11.5px; color: var(--fl-faint); }

#rs .adv summary { cursor: pointer; font-size: 11px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--fl-muted); list-style: none; display: flex; align-items: center; gap: 6px; }
#rs .adv summary::-webkit-details-marker { display: none; }
#rs .adv summary:focus-visible { outline: 2px solid var(--fl-accent); outline-offset: 2px; border-radius: 6px; }
/* Disclosure triangle driven by the native [open] state so it can never go
